    const form = document.getElementById('quiz-form');
    const checkboxes = document.querySelectorAll('.question-checkbox');

    checkboxes.forEach(checkbox => {
      checkbox.addEventListener('change', (e) => {
        const questionId = e.target.name;
        const selectedOptions = Array.from(
          document.querySelectorAll(`input[name="${questionId}"]:checked`)
        ).map(cb => cb.value);

        this.answers[questionId] = selectedOptions;
      });
    });

    form.addEventListener('submit', (e) => {
      e.preventDefault();
      this.handleSubmit();
    });
  }

  handleSubmit() {
    const successMessage = document.getElementById('success-message');
    const resultsHtml = this.generateResults();

    successMessage.innerHTML = `
      <strong>Thank you for completing the quiz!</strong>
      <p>Your responses have been recorded:</p>
      <ul class="results-list">
        ${resultsHtml}
      </ul>
    `;

    successMessage.classList.add('show');
    successMessage.focus();

    console.log('Quiz responses:', this.answers);
  }

  generateResults() {
    return quizData.map(question => {
      const selectedCount = this.answers[question.id]?.length || 0;
