            })
            .join(', ')
        : '(No selection)';

      return `<li><strong>${this.escapeHtml(question.question)}</strong><br>${this.escapeHtml(selectedText)}</li>`;
    }).join('');
  }

  escapeHtml(text) {
    const div = document.createElement('div');
    div.textContent = text;
    return div.innerHTML;
  }
}

