+      { id: 'q1-c', text: 'JavaScript' },
+      { id: 'q1-d', text: 'C++' }
+    ]
+  },
+  {
+    id: 'q2',
+    question: 'Which languages are commonly used for web backend development?',
+    options: [
+      { id: 'q2-a', text: 'Node.js (JavaScript)' },
+      { id: 'q2-b', text: 'Python' },
+      { id: 'q2-c', text: 'HTML' },
+      { id: 'q2-d', text: 'Go' }
+    ]
+  },
+  {
+    id: 'q3',
+    question: 'Which of these support functional programming paradigms?',
+    options: [
+      { id: 'q3-a', text: 'Rust' },
+      { id: 'q3-b', text: 'Haskell' },
+      { id: 'q3-c', text: 'Lisp' },
+      { id: 'q3-d', text: 'COBOL' }
+    ]
+  }
+];
+
+class QuizApp {
+  constructor(rootElement) {
+    this.root = rootElement;
+    this.answers = {};
+    this.render();
+    this.attachEventListeners();
+  }
+
+  render() {
+    this.root.innerHTML = `
+      <div class="quiz-container">
+        <div class="quiz-header">
+          <h1>Computer Languages Quiz</h1>
+          <p>Select all correct answers for each question</p>
+        </div>
+        <form id="quiz-form" novalidate>
+          ${quizData.map(q => this.renderQuestion(q)).join('')}
+          <button type="submit" class="submit-button">Submit Quiz</button>
+        </form>
+        <div class="success-message" id="success-message">
+          <strong>Thank you for completing the quiz!</strong>
+          <p>Your responses have been recorded.</p>
+        </div>
+      </div>
+    `;
+  }
+
+  renderQuestion(question) {
+    const helpTextId = question.helpText ? `${question.id}-help` : '';
+    const hasHelpText = question.helpText ? `aria-describedby="${helpTextId}"` : '';
+
+    return `
+      <fieldset class="form-field" id="${question.id}-fieldset" ${hasHelpText}>
+        <legend>${this.escapeHtml(question.question)}</legend>
+        ${question.helpText ? `<p id="${helpTextId}" class="form-field-help">${this.escapeHtml(question.helpText)}</p>` : ''}
+        <div class="checkbox-group">
+          ${question.options.map(option => this.renderCheckbox(question.id, option)).join('')}
+        </div>
+      </fieldset>
+    `;
+  }
+
+  renderCheckbox(questionId, option) {
+    return `
+      <div class="checkbox-wrapper">
+        <input 
+          type="checkbox" 
+          id="${option.id}" 
+          name="${questionId}" 
+          value="${option.id}"
+          class="question-checkbox"
+        >
+        <label for="${option.id}">${this.escapeHtml(option.text)}</label>
+      </div>
+    `;
+  }
+
+  attachEventListeners() {
+    const form = document.getElementById('quiz-form');
+    const checkboxes = document.querySelectorAll('.question-checkbox');
+
+    checkboxes.forEach(checkbox => {
+      checkbox.addEventListener('change', (e) => {
+        const questionId = e.target.name;
+        const selectedOptions = Array.from(
+          document.querySelectorAll(`input[name="${questionId}"]:checked`)
+        ).map(cb => cb.value);
+
+        this.answers[questionId] = selectedOptions;
+      });
+    });
+
+    form.addEventListener('submit', (e) => {
+      e.preventDefault();
+      this.handleSubmit();
+    });
+  }
+
+  handleSubmit() {
+    const successMessage = document.getElementById('success-message');
+    const resultsHtml = this.generateResults();
+
+    successMessage.innerHTML = `
+      <strong>Thank you for completing the quiz!</strong>
+      <p>Your responses have been recorded:</p>
+      <ul class="results-list">
+        ${resultsHtml}
+      </ul>
+    `;
+
+    successMessage.classList.add('show');
+    successMessage.focus();
+
+    console.log('Quiz responses:', this.answers);
+  }
+
+  generateResults() {
+    return quizData.map(question => {
+      const selectedCount = this.answers[question.id]?.length || 0;
+      const selectedText = selectedCount > 0
+        ? this.answers[question.id]
+            .map(optionId => {
+              const option = question.options.find(o => o.id === optionId);
+              return option ? option.text : '';
+            })
+            .join(', ')
+        : '(No selection)';
+
+      return `<li><strong>${this.escapeHtml(question.question)}</strong><br>${this.escapeHtml(selectedText)}</li>`;
+    }).join('');
+  }
+
+  escapeHtml(text) {
+    const div = document.createElement('div');
+    div.textContent = text;
+    return div.innerHTML;
+  }
+}
+
+document.addEventListener('DOMContentLoaded', () => {
+  const appRoot = document.getElementById('app');
+  new QuizApp(appRoot);
+});
+
')

