  {
    id: 'q1',
    question: 'Which of the following are dynamically-typed languages?',
    helpText: 'Dynamically-typed languages determine variable types at runtime rather than at compile time.',
    options: [
      { id: 'q1-a', text: 'Python' },
      { id: 'q1-b', text: 'Java' },
      { id: 'q1-c', text: 'JavaScript' },
      { id: 'q1-d', text: 'C++' }
    ]
  },
  {
    id: 'q2',
    question: 'Which languages are commonly used for web backend development?',
    options: [
      { id: 'q2-a', text: 'Node.js (JavaScript)' },
      { id: 'q2-b', text: 'Python' },
      { id: 'q2-c', text: 'HTML' },
      { id: 'q2-d', text: 'Go' }
    ]
  },
  {
    id: 'q3',
    question: 'Which of these support functional programming paradigms?',
    options: [
      { id: 'q3-a', text: 'Rust' },
      { id: 'q3-b', text: 'Haskell' },
      { id: 'q3-c', text: 'Lisp' },
      { id: 'q3-d', text: 'COBOL' }
    ]
  }
];

class QuizApp {
  constructor(rootElement) {
    this.root = rootElement;
    this.answers = {};
    this.render();
    this.attachEventListeners();
  }

  render() {
    this.root.innerHTML = `
      <div class="quiz-container">
        <div class="quiz-header">
          <h1>Computer Languages Quiz</h1>
          <p>Select all correct answers for each question</p>
        </div>
        <form id="quiz-form" novalidate>
          ${quizData.map(q => this.renderQuestion(q)).join('')}
          <button type="submit" class="submit-button">Submit Quiz</button>
        </form>
        <div class="success-message" id="success-message">
          <strong>Thank you for completing the quiz!</strong>
          <p>Your responses have been recorded.</p>
        </div>
      </div>
    `;
  }

  renderQuestion(question) {
    const helpTextId = question.helpText ? `${question.id}-help` : '';
    const hasHelpText = question.helpText ? `aria-describedby="${helpTextId}"` : '';

    return `
      <fieldset class="form-field" id="${question.id}-fieldset" ${hasHelpText}>
        <legend>${this.escapeHtml(question.question)}</legend>
        ${question.helpText ? `<p id="${helpTextId}" class="form-field-help">${this.escapeHtml(question.helpText)}</p>` : ''}
        <div class="checkbox-group">
          ${question.options.map(option => this.renderCheckbox(question.id, option)).join('')}
        </div>
      </fieldset>
    `;
  }

  renderCheckbox(questionId, option) {
    return `
      <div class="checkbox-wrapper">
        <input 
          type="checkbox" 
          id="${option.id}" 
          name="${questionId}" 
          value="${option.id}"
          class="question-checkbox"
        >
        <label for="${option.id}">${this.escapeHtml(option.text)}</label>
      </div>
    `;
  }

  attachEventListeners() {
    const form = document.getElementById('quiz-form');
    const checkboxes = document.querySelectorAll('.question-checkbox');

